import { Box, Typography, Stack } from '@mui/material';
import HighlightOffIcon from '@mui/icons-material/HighlightOff';
import { useNavigate } from 'react-router-dom';
import GlowButton from '../components/ui/GlowButton';
import { useSignup } from '../context/SignupContext';

import { BRAND, TOKENS } from '../theme';

const cardSx = {
  width: '100%',
  maxWidth: 520,
  mx: 'auto',
  p: { xs: 3, sm: 4.5 },
  borderRadius: '24px',
  border: `1px solid ${TOKENS.colors.border}`,
  bgcolor: TOKENS.card.bgcolor,
  backdropFilter: 'blur(28px)',
};

const PaymentCancelPage = () => {
  const navigate = useNavigate();
  const { signupData, selectedPlan } = useSignup();

  const resumePath = () => {
    if (signupData?.email && selectedPlan?.planId) return '/checkout';
    if (signupData?.email) return '/plans';
    return '/signup-landingpage';
  };

  const resumeLabel = () => {
    if (signupData?.email && selectedPlan?.planId) return 'Back to Checkout';
    if (signupData?.email) return 'Back to Plans';
    return 'Back to Home';
  };

  return (
    <Box sx={{ px: { xs: 1, sm: 0 } }}>
      <Box sx={cardSx}>
        <Stack spacing={3} alignItems="center">
          <Box
            sx={{
              width: 80,
              height: 80,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              bgcolor: TOKENS.colors.surface,
              border: `1px solid ${TOKENS.colors.border}`,
            }}
          >
            <HighlightOffIcon sx={{ fontSize: 48, color: 'text.secondary' }} />
          </Box>

          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h4" sx={{ fontWeight: 800, mb: 1, fontSize: { xs: '1.5rem', sm: '1.75rem' } }}>
              Payment cancelled
            </Typography>
            <Typography variant="body1" sx={{ color: 'text.secondary', px: 1 }}>
              No charge was made. You can continue whenever you're ready.
            </Typography>
          </Box>

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ width: '100%' }}>
            <GlowButton fullWidth variant="outlined" onClick={() => navigate('/signup-landingpage')}>
              Home
            </GlowButton>
            <GlowButton fullWidth onClick={() => navigate(resumePath())}>
              {resumeLabel()}
            </GlowButton>
          </Stack>
        </Stack>
      </Box>
    </Box>
  );
};

export default PaymentCancelPage;
